        style={{ justifyContent: JUSTIFY[skin.align] ?? "flex-start" }}
      >
        {review.source === "facebook" ? (
          review.recommended ? (
            <span className="flex items-center gap-1" style={skin.rating}>
              <ThumbsUp className="size-4" /> Recommended
