function CampaignsPage({ campaigns, setCampaigns, setTemplates, onOpen, onNew, onStop, onRestart, onPreview }) {
  const [statusFilter, setStatusFilter] = useState("all");
  const [modeFilter, setModeFilter] = useState("all");
  const [renameId, setRenameId] = useState(null);
  const [renameValue, setRenameValue] = useState("");
  const [deleteTarget, setDeleteTarget] = useState(null);
  // SORTABLE HEADERS, AS IN REVIEW MANAGER (Ali, 17 Sep: "Lets have them all
  // as DataTables, easier"). Empty to start, so the rows keep the
  // what-is-happening order below until someone presses a header.
  const [sorting, setSorting] = useState([]);

  const rows = useMemo(
    () =>
      [...campaigns]
        .filter(
          (c) =>
            (statusFilter === "all" || c.status === statusFilter) &&
            (modeFilter === "all" || c.config.channel === modeFilter),
        )
        .sort(
          (a, b) =>
            (STATUS_ORDER[a.status] ?? 9) - (STATUS_ORDER[b.status] ?? 9) ||
            (b.stats?.reviews ?? -1) - (a.stats?.reviews ?? -1),
        ),
    [campaigns, statusFilter, modeFilter],
  );
  const filtered = statusFilter !== "all" || modeFilter !== "all";
  const { top, bandRef, headTop } = useStickyTable("get-reviews-page-header");

  const commitRename = () => {
    setCampaigns((cs) => cs.map((x) => (x.id === renameId ? { ...x, name: renameValue || x.name } : x)));
    setRenameId(null);
  };

  // SAVE AS TEMPLATE is the only way a user template is made. The config is
  // copied clean — no id, the two send-step confirmations unticked — so a
  // campaign made from it later starts where a new one should.
  const saveAsTemplate = (c) =>
    setTemplates((ts) => [
      {
        id: `t${Date.now()}`,
        name: c.name,
        updated: new Date().toISOString(),
        config: { ...c.config, id: null, permission: false, privacy: false },
      },
      ...ts,
    ]);

  const columns = useMemo(
    () => [
      {
        accessorKey: "name",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Campaign" dataHook="campaigns-col-campaign" />,
        // EVERY TEXT COLUMN SAYS HOW IT SORTS. TanStack's "auto" only samples
        // rows after the tenth, so a list of nine falls back to a raw compare
        // and "alpha" sorts after "Zeta".
        sortingFn: (a, b, id) => a.getValue(id).localeCompare(b.getValue(id)),
        cell: ({ row }) => {
          const c = row.original;
          if (renameId === c.id) {
            return (
              <Input
                dataHook={`campaign-${c.id}-rename`}
                value={renameValue}
                autoFocus
                onChange={(e) => setRenameValue(e.target.value)}
                onBlur={commitRename}
                onKeyDown={(e) => {
                  if (e.key === "Enter") e.currentTarget.blur();
                }}
              />
            );
          }
          return (
            /* data-bl-link, the shell's link rule (3 Sep): foreground at
               rest, green-700 + underline on hover. The name is the way in;
               a Draft opens in the wizard where it left off, everything else
               opens its page. */
            <button
              type="button"
              data-bl-link=""
              data-hook={`campaign-${c.id}-open`}
              onClick={() => onOpen(c)}
              className="text-left font-medium whitespace-nowrap"
            >
              {c.name}
            </button>
          );
        },
      },
      {
        id: "mode",
        // An accessor, because TanStack will not sort a column without one:
        // the DS header then renders a plain label. Sorts by the word shown.
        accessorFn: (c) => CHANNELS[c.config.channel]?.label ?? "",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Mode" dataHook="campaigns-col-mode" />,
        sortingFn: (a, b, id) => a.getValue(id).localeCompare(b.getValue(id)),
        cell: ({ row }) => (
          <span className="text-muted-foreground">{CHANNELS[row.original.config.channel]?.label ?? ""}</span>
        ),
      },
      {
        // TYPE, ALONGSIDE MODE (Ali, 7 Sep). The two answer different
        // questions and neither implies the other: Mode is how the invite
