                    <MoreHorizontal className="size-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  {c.config.channel === "kiosk" ? (
                    <DropdownMenuItem onSelect={() => onPreview(c)}>
                      <Monitor className="size-4" /> Open kiosk
