                  {c.status === "Draft" ? (
                    <DropdownMenuItem onSelect={() => setDeleteTarget({ kind: "campaign", item: c })}>
                      <Trash2 className="size-4" /> Delete draft
                    </DropdownMenuItem>
                  ) : null}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          );
        },
      },
    ],
    [renameId, renameValue, onOpen, onNew, onStop, onRestart, onPreview],
  );

  const table = useDataTable({
    columns,
    data: rows,
    getRowId: (row) => row.id,
    sorting,
