                  </TableCell>
                  <TableCell className="text-muted-foreground">
                    <DateStamp label="Updated" value={t.updated} dataHook={`template-${t.id}-updated`} />
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1.5">
                      <Button
                        variant="outline"
                        size="sm"
