        id: "reviews",
        accessorFn: (c) => (c.stats ? c.stats.reviews : -1),
        header: ({ column }) => (
          <DataTableColumnHeader column={column} title="Reviews gained" align="right" dataHook="campaigns-col-reviews" />
        ),
        sortingFn: byNumber,
        cell: ({ row }) => (
          <span className="block text-right font-semibold tabular-nums">
            {row.original.stats ? (
